mapper.select:
select 
from litemall_mail_outbox
where deleted = 0 and status = 'pending' and send_at <= #{now}
order by id asc
limit #{limit}

mapper.update:
update litemall_mail_outbox
set status = 'sent', attempts = attempts + 1, last_error = null, update_time = #{now}
where id = #{id} and status = 'pending' and deleted = 0

update litemall_mail_outbox
set status = 'failed', attempts = attempts + 1, last_error = #{lastError}, update_time = #{now}
where id = #{id} and status = 'pending' and deleted = 0

update litemall_mail_outbox
set attempts = attempts + 1, last_error = #{lastError}, update_time = #{now}
where id = #{id} and status = 'pending' and deleted = 0

update litemall_mail_outbox
set status = 'pending', attempts = 0, last_error = null, send_at = #{now}, update_time = #{now}
where id = #{id} and status = 'failed' and deleted = 0

